// ---------- OUTILS ----------
function lerp(a,b,t){return a+(b-a)*t;}
function chemin(a,b,yRoute=ROUTE_Y){return [a,{x:a.x,y:yRoute},{x:b.x,y:yRoute},b];}
function surChemin(pts,t){ // t 0..1
 let L=0;const seg=[];for(let i=1;i<pts.length;i++){const d=Math.hypot(pts[i].x-pts[i-1].x,pts[i].y-pts[i-1].y);seg.push(d);L+=d;}
 let r=Math.max(0,Math.min(1,t))*L;
 for(let i=1;i<pts.length;i++){if(r<=seg[i-1]||i===pts.length-1){const k=seg[i-1]?Math.min(1,r/seg[i-1]):1;const a=pts[i-1],b=pts[i];return {x:lerp(a.x,b.x,k),y:lerp(a.y,b.y,k),dir:dirDe(b.x-a.x,b.y-a.y)};}r-=seg[i-1];}
 return {...pts[pts.length-1],dir:3};
}
function surBoucle(pts,dist){ // déplacement continu sur un circuit fermé
 const p=pts.concat([pts[0]]);let L=0;const seg=[];for(let i=1;i<p.length;i++){const d=Math.hypot(p[i].x-p[i-1].x,p[i].y-p[i-1].y);seg.push(d);L+=d;}
 let r=((dist%L)+L)%L;for(let i=1;i<p.length;i++){if(r<=seg[i-1]){const k=r/seg[i-1];return {x:lerp(p[i-1].x,p[i].x,k),y:lerp(p[i-1].y,p[i].y,k),dir:dirDe(p[i].x-p[i-1].x,p[i].y-p[i-1].y)};}r-=seg[i-1];}
 return {...p[0],dir:3};
}
function dirDe(dx,dy){return Math.abs(dx)>Math.abs(dy)?(dx>0?0:2):(dy<0?1:3);} // 0 droite 1 haut 2 gauche 3 bas

