let G={mode:'menu',queue:[],mem:{codeAppris:false,mamiPhraseConnue:false},reveil:0,minute:0,prologue:false,L:null,player:{scene:'chambre',x:110,y:150,dir:3},keypad:null,fin:null,log:[],pro:null,suiveur:null,trail:[]};
