function suivre(dt){
 const S=G.suiveur;if(!(G.prologue&&G.pro&&G.pro.etape==='matin'&&S))return;
 const tr=G.trail;if(tr.length<7){S.marche=false;return;}
 const t=tr[tr.length-7];if(t.scene!==S.scene){S.scene=t.scene;S.x=t.x;S.y=t.y;return;}
 const dx=t.x-S.x,dy=t.y-S.y,d=Math.hypot(dx,dy);
 if(d<2){S.marche=false;return;}
 const st=Math.min(d,420*dt);S.x+=dx/d*st;S.y+=dy/d*st;S.dir=dirDe(dx,dy);S.marche=true;
}
function objectif(){
 if(G.mode!=='jeu')return null;const pl=G.player;let o=null;
 if(G.prologue&&G.pro){const e=G.pro.etape;
  if(e==='matin')o={t:'Emmène Loulou à l\'école (grand bâtiment rouge, en bas à droite)',x:ECOLE.x,y:ECOLE.y,scene:'village'};
  else if(e==='retour')o={t:'Rentre à la maison pour la sieste (toit orange, en haut à gauche)',x:PORTES_V[0].x,y:PORTES_V[0].y,scene:'village'};
  else if(e==='reveil')o={t:'Aaron est en retard : cours à l\'école parler à Marc',x:ECOLE.x,y:ECOLE.y+7,scene:'village'};
  if(o&&pl.scene!=='village'){const d=pl.scene==='chambre'?{x:211,y:306}:{x:256,y:306};o={...o,x:d.x,y:d.y,scene:pl.scene};}
  return o;}
 if(G.prologue)return null;
 const c=consigne();if(!c.cur)return {t:c.t,scene:null};
 const cu=c.cur;let txt='Maintenant : '+pub(cu.t)+(c.suite?'   ·   Ensuite : '+pub(c.suite.t):'');
 let tg=null;
 if(cu.to){const p=PORTES_V.find(q=>q.id===cu.to);tg={scene:'village',x:p.x,y:p.y};}
 else if(cu.pt==='cle'){tg={scene:'village',x:P.cleSol.x,y:P.cleSol.y};}
 else if(cu.pm){const mp=machinePos();tg={scene:'salon',x:mp.x,y:mp.y+14};}
 else if(cu.sc){tg={scene:cu.sc,x:cu.x,y:cu.y};}
 if(!tg)return {t:txt,scene:null};
 if(tg.scene!==pl.scene){
  if(pl.scene==='village'){const id=tg.scene==='chambre'?'p_aaron':'p_benjamin';const p=PORTES_V.find(q=>q.id===id);tg={scene:'village',x:p.x,y:p.y};}
  else if(pl.scene==='salon'&&tg.scene==='soussol'){const mp=machinePos();tg={scene:'salon',x:mp.x,y:mp.y+14};}
  else{const d=sortieInt(pl.scene)||echellePos();tg={scene:pl.scene,...d};}}
 return {t:txt,...tg};
}
function coupe(sp){return sp.sol?Math.max(0,sp.sol[1]+sp.sol[3]-14):sp.h;}
function degager(){const pl=G.player,S=solids(pl.scene),R=SC[pl.scene];
 const dans=(x,y)=>S.some(r=>x+6>r[0]&&x-6<r[0]+r[2]&&y>r[1]&&y-3<r[1]+r[3]);
 if(!dans(pl.x,pl.y))return false;
 for(let d=4;d<=240;d+=4)for(let a=0;a<16;a++){const x=pl.x+Math.cos(a*Math.PI/8)*d,y=pl.y+Math.sin(a*Math.PI/8)*d;if(x>8&&x<R.w-8&&y>12&&y<R.h-2&&!dans(x,y)){pl.x=x;pl.y=y;return true;}}
 return false;}
