// ---------- ÉVÉNEMENTS DU TEMPS ----------
function avancer(dtMin){
 if(!tempsActif()&&!(G.keypad&&G.mode==='jeu'&&!G.prologue)) return;
 const a=G.minute,b=Math.min(20,a+dtMin);G.minute=b;evenements(a,b);
}
function evenements(a,b){
 const L=G.L;const passe=x=>a<x&&b>=x;
 if(passe(4)&&!L.cleEnMain&&!L.cleReprise) L.cleAuSol=true;
 if(passe(7)&&L.cleAuSol){L.cleAuSol=false;reprise('village',P.porteDevantPharma,7);}
 if(passe(12)&&L.machineBougee&&!L.trappeOuverte&&!(L.cleReprise&&L.repriseA<10)){L.surpris=true;L.perdu=true;if(G.player.scene==='salon') say('ben_quoi');}
 if(L.cleUtilisee&&!L.trappeOuverte&&!L.cadenasBloque&&b>L.codeLimite){L.cadenasBloque=true;L.perdu=true;G.keypad=null;if(G.player.scene==='salon') say('trappe_bloquee');}
 if(b>=20&&a<20) mourir();
}
function reprise(scene,pos,m){const L=G.L;L.cleReprise=true;L.perdu=true;L.repriseA=m;L.repriseDe={scene,x:pos.x,y:pos.y};}
function mourir(){G.keypad=null;say('mort');G.queue.push({fx:'noir'});call(()=>demarrerBoucle());}
function regler(m){ // panneau de test
 const a=G.minute;if(m>a) evenements(a,Math.min(m,19.99));G.minute=Math.min(m,19.99);
}

// ---------- INTERACTIONS ----------
function proche(a,b,r){return Math.hypot(a.x-b.x,a.y-b.y)<=r;}
function interactifs(){
 const pl=G.player,L=G.L,list=[],pos=positions();
 for(const id in pos){const n=pos[id];if(n.scene===pl.scene) list.push({id,type:'pnj',x:n.x,y:n.y,r:44});}
 if(pl.scene==='village'){
  if(L.cleAuSol) list.push({id:'cle',type:'obj',...P.cleSol,r:36});
  if(G.minute>=6&&!G.prologue) list.push({id:'mot',type:'obj',x:BATM.Maison_Paul[1]+130,y:BATM.Maison_Paul[2]+444,r:30});
  for(const p of PORTES_V) if(!BATM[p.own].off) list.push({id:p.id,type:'porte',x:p.x,y:p.y,r:52});
 }
 if(pl.scene==='chambre'){const c=itemDe('chambre','commode'),f=itemDe('chambre','fenetre_cassee'),r=itemDe('chambre','radiateur');
  if(c)list.push({id:'meuble',type:'obj',x:c[0]+SPRI.commode.w/2,y:c[1]+12,r:40});
  if(f)list.push({id:'fenetre',type:'obj',x:f[0]+SPRI.fenetre_cassee.w/2,y:f[1]+50,r:34});
  if(r)list.push({id:'chauffage',type:'obj',x:r[0]+SPRI.radiateur.w/2,y:r[1]+42,r:30});}
 if(pl.scene==='salon'&&itemDe('salon','machine')){const m=machinePos(),b=machineBase();list.push({id:'machine',type:'obj',x:m.x,y:m.y+14,r:44});if(L.machineBougee) list.push({id:'trappe',type:'obj',x:b.x,y:b.y+10,r:30});}
 if(pl.scene==='soussol'){if(itemDe('soussol','trappe_bas'))list.push({id:'echelle',type:'obj',...echellePos(),r:36});if(!L.dogFed) list.push({id:'chien',type:'obj',x:P.soussolChien.x,y:P.soussolChien.y,r:46});}
 if(pl.scene!=='village')for(const it of ITEMS[pl.scene])if(it[2]==='porte'){list.push({id:'porteint',type:'porteint',ref:it,x:it[0]+16,y:it[1]+10,r:40});list.push({id:'porteint',type:'porteint',ref:it,x:it[0]+16,y:it[1]-SPRI.porte.h-8,r:40});}
 return list;
}
function cible(){
 const pl=G.player;let best=null,bd=1e9;
 for(const it of interactifs()){const d0=Math.hypot(it.x-pl.x,it.y-pl.y),d=d0-(it.type==='porteint'?14:0);if(d0<=it.r&&d<bd){bd=d;best=it;}}
 return best;
}
function interagir(){
 if(G.mode!=='jeu'||G.queue.length||G.keypad) return false;
 const c=cible();if(!c) return false;
 if(c.type==='pnj') parler(c.id); else if(c.type==='porte') porte(c.id); else if(c.type==='porteint') porteInt(c.ref); else objet(c.id);
 return true;
}
function parler(id){
 const L=G.L,m=G.minute;
 if(G.prologue){ const e=G.pro&&G.pro.etape; if(id==='marc'&&e==='reveil'){say('prologue_ecole');say('prologue_recherche');G.queue.push({fx:'noir'});say('mort');G.queue.push({fx:'noir'});call(()=>demarrerBoucle());} else if(id==='nathalie'&&e==='reveil') say('nat_pressee'); else if(id==='loulou'&&e==='matin') say('matin_loulou'); else say(e==='matin'?'matin_autre':e==='retour'?'retour_autre':'prologue_autre'); return; }
 const deja=L.parle[id];L.parle[id]=true;
 if(['zm','zoe','zp'].includes(id)){const d2=L.parle.zoeFam;L.parle.zoeFam=true;if(!d2)say('zoe_premiere');else if(L.cleEnMain)say('zoe_cle');else say('zoe_encore');return;}
 switch(id){
  case 'reda': if(!deja){say('reda_premiere');L.vuReda=true;if(L.braceletVu){say('reda_bracelet');L.redaBracelet=true;}}
   else if(L.braceletVu&&!L.redaBracelet){say('reda_bracelet');L.redaBracelet=true;} else if(L.cleEnMain) say('reda_cle'); else say('reda_encore'); break;
  case 'cedric': if(!deja){say('cedric_premiere');L.aLaViande=true;} else if(L.cleEnMain) say('cedric_cle'); else say('cedric_encore'); break;
  case 'lilya': if(!deja){say('lilya_premiere');if(L.cleEnMain){say(G.mem.mamiPhraseConnue?'lilya_cle_su':'lilya_cle');L.lilyaCle=true;}}
   else if(L.cleEnMain&&!L.lilyaCle){say(G.mem.mamiPhraseConnue?'lilya_cle_su':'lilya_cle');L.lilyaCle=true;} else say('lilya_encore'); break;
  case 'marc': if(!deja) say('marc_premiere'); else if(L.cleEnMain) say('marc_cle'); else say('marc_encore'); break;
  case 'mami': if(!L.cleEnMain) say('mami_silence'); else if(!L.mamiParle){say(G.mem.mamiPhraseConnue?'mami_cle_su':'mami_cle');L.mamiParle=true;G.mem.mamiPhraseConnue=true;} else say('mami_sourit'); break;
  case 'paul': if(L.cleEnMain&&!L.paulCle){say('paul_cle');L.paulCle=true;break;}
   if(m<6){L.paulIdx=L.paulIdx%8+1;say('paul_'+L.paulIdx);} else say(L.cleReprise?'paul_rue_reprise':'paul_rue'); break;
  case 'benjamin': if(L.cleEnMain) choix([{label:'Parler',fn:()=>parlerBen()},{label:'Rendre la clé',fn:()=>{say('ben_rendre');donnerCle();}}]); else parlerBen(); break;
  case 'nathalie': if(L.cleEnMain) choix([{label:'Parler',fn:()=>parlerNat()},{label:'Rendre la clé',fn:()=>{say('nat_rendre');donnerCle();}}]); else parlerNat(); break;
  case 'loulou': fin(); break;
 }
}
function parlerBen(){
 const L=G.L,m=G.minute,b=benjamin(m);
 if(b.dehors){say('ben_dehors');return;}
 if(L.cleReprise){say('ben_reprise');return;}
 if(m>=12){say('ben_retour');return;}
 if(m>=8){if(!L.benSeulDit){say('ben_seul');L.benSeulDit=true;}else say('ben_paul');return;}
 if(L.vuReda&&!L.benApres){say('ben_apres_poste');L.benApres=true;G.mem.codeAppris=true;L.parle.benjamin=true;return;}
 if(!L.parle.benAvant&&!L.benApres){L.parle.benAvant=true;say('ben_avant_poste');if(L.parle.cedric&&!L.vuReda) say('ben_chien_avant');return;}
 say('ben_encore');
}
function parlerNat(){
 const L=G.L,m=G.minute,n=nathalie(m);
 if(L.cleReprise&&n.maison){say('nat_fatiguee');return;}
 if(n.cherche){if(!L.natAlliance){say('nat_alliance');L.natAlliance=true;}else say('nat_encore');return;}
 say('nat_pressee');
}
function donnerCle(){const L=G.L;L.cleEnMain=false;const n=nathalie(G.minute);reprise(n.scene==='village'?'village':'salon',{x:n.x||550,y:n.y||632},G.minute);}
function presentAuSalon(){const m=G.minute;return {ben:benjamin(m).scene==='salon',nat:nathalie(m).scene==='salon'};}
function objet(id){
 const L=G.L;
 if(G.prologue&&!['fenetre','meuble','chauffage'].includes(id)){say('prologue_autre');return;}
 switch(id){
  case 'meuble': say('aaron_meuble');L.braceletVu=true;break;
  case 'fenetre': say('aaron_fenetre');break;
  case 'chauffage': say('aaron_chauffage');break;
  case 'cle': L.cleAuSol=false;L.cleEnMain=true;say('aaron_cle');break;
  case 'mot': say('paul_mot');break;
  case 'machine': case 'trappe': machine();break;
  case 'echelle': {const a=arriveeSalon();changerScene('salon',a.x,a.y,3);}break;
  case 'chien': if(L.aLaViande){say('chien_viande');L.aLaViande=false;L.dogFed=true;} else say('chien_bloque');break;
 }
}
function machine(){
 const L=G.L,pr=presentAuSalon();
 if(pr.ben){ if(!L.machineVue&&!L.machineBougee){say('ben_machine');L.machineVue=true;} else say('ben_quoi'); return; }
 if(pr.nat){ say('nat_quoi'); return; }
 if(!L.machineBougee){L.machineBougee=true;say('trappe_decouverte');}
 if(L.cadenasBloque){say('trappe_bloquee');return;}
 if(L.trappeOuverte){const a=arriveeSoussol();changerScene('soussol',a.x,a.y,3);return;}
 if(!L.cleEnMain){say('trappe_pas_cle');return;}
 if(!L.cleUtilisee){L.cleUtilisee=true;L.codeLimite=G.minute+1;}
 if(!G.mem.codeAppris){say('trappe_pas_code');return;}
 call(()=>{G.keypad={value:''};});
}
function code(valeur){
 const L=G.L;G.keypad=null;
 if(valeur==='080912'){L.trappeOuverte=true;{const a=arriveeSoussol();changerScene('soussol',a.x,a.y,3);}return true;}
 L.cadenasBloque=true;L.perdu=true;say('trappe_bloquee');return false;
}
function changerScene(s,x,y,dir){G.player.scene=s;G.player.x=x;G.player.y=y;G.player.dir=dir;if(G.suiveur&&G.pro&&G.pro.etape==='matin'){G.suiveur={scene:s,x:x-10,y:y+16,dir:dir,marche:false};G.trail=[];}}
function fin(){
 say('loulou');G.queue.push({fx:'noir'});titre('Hôpital');say('hopital');
 call(()=>{G.mode='lettre';G.fin={page:0};});
}

// ---------- DÉPLACEMENT DU JOUEUR ----------
function bouger(dx,dy,dt){
 const pl=G.player;if(G.mode!=='jeu'||G.queue.length||G.keypad) return false;
 const v=VIT*dt;let nx=pl.x+dx*v,ny=pl.y+dy*v;
 if(dx||dy) pl.dir=dirDe(dx,dy);
 const S=solids(pl.scene),R=SC[pl.scene];
 const libre=(x,y)=>x>8&&x<R.w-8&&y>12&&y<R.h-2&&!S.some(r=>x+6>r[0]&&x-6<r[0]+r[2]&&y>r[1]&&y-3<r[1]+r[3]);
 if(libre(nx,pl.y)) pl.x=nx; if(libre(pl.x,ny)) pl.y=ny;
 for(const p of PORTES){if(p.auto!==false&&p.scene===pl.scene&&pl.x>p.x&&pl.x<p.x+p.w&&pl.y>p.y&&pl.y<p.y+p.h){
   if(G.prologue&&p.to==='salon'){pl.y+=16;say(G.pro.etape==='matin'?'matin_autre':G.pro.etape==='retour'?'retour_autre':'prologue_autre');break;}
   if(G.prologue&&p.to==='chambre'&&G.pro.etape==='retour'){sieste();break;}
   changerScene(p.to,p.tx,p.ty,p.dir);break;}}
 {const I=INTS[pl.scene];if(I&&I.gap&&pl.y>SC[pl.scene].h-14&&pl.x>I.gap[0]&&pl.x<I.gap[1]){const a=arriveeVillage(pl.scene);changerScene('village',a.x,a.y,3);}}
 if(pl.scene!=='village'&&ITEMS[pl.scene]){const R2=SC[pl.scene];for(const it of ITEMS[pl.scene]){if(it[2]!=='passage')continue;const sp=SPRI.passage;if(pl.x>it[0]+6&&pl.x<it[0]+sp.w-6&&((it[1]<=80&&pl.y<=76)||(it[1]>=R2.h-20&&pl.y>R2.h-14))){passageInt(it);break;}}}
 {const tr=G.trail,l=tr[tr.length-1];if(!l||l.scene!==pl.scene||Math.hypot(pl.x-l.x,pl.y-l.y)>=5){tr.push({scene:pl.scene,x:pl.x,y:pl.y});if(tr.length>300)tr.shift();}}
 if(G.prologue&&G.pro&&G.pro.etape==='matin'&&pl.scene==='village'&&Math.hypot(pl.x-ECOLE.x,pl.y-ECOLE.y)<64)deposerLoulou();
 return true;
}
if(typeof module!=='undefined') module.exports={etirerRoute,etirerMur,agrandirVillage,villageExport,VOFF,MURS,redimMur,ROUTES,redimRoute,majTrajets,trajets:()=>({ROUTE_Y,RECHERCHE,BALADE_PAUL}),setPublic:v=>{MODE_PUBLIC=v;},pub,agrandir,geomExport,geomImport,passageInt,PBASE,BASE_GEOM,STYLES,creerPiece,supprimerPiece,porteInt,libreIn,recreerPiece,INTS,ENTREES,arriveeVillage,DOOR,ITEMS,SPRI,itemDe,collItem,machineBase,echellePos,coupe,degager,consigne,etapes,SPR,BATM,P,planExporter,planImporter,planReinit,appliquerPlan,BUISSONS,FIXES,sauter,objectif,porte,suivre,sieste,deposerLoulou,PORTES_V,ECOLE,G,D,NOMS,LETTRE,MESSAGE_FINAL,AJOUTS_DEMO,nouvellePartie,demarrerBoucle,avancer,regler,interagir,parler,objet,code,positions,bouger,cible,changerScene,nathalie,benjamin,tempsActif,numeroBoucle,solids,machinePos,SC,BAT};
